// ─── Voz ────────────────────────────────────────────────────────────────────

move_voice: {
	key: "move_voice",
	category: "voice",
	label: "Mover a otro canal de voz",
	description: "Sólo funciona si la persona está conectada a voz.",
	requires: ["member"],
	permission: "MoveMembers",
	params: [
		{
			key: "channel",
			type: "channel",
			required: false,
			label: "Canal de destino",
			hint: "Déjalo vacío para desconectarla de la voz.",
			default: null
		}
	]
},

voice_mute: {
	key: "voice_mute",
	category: "voice",
	label: "Silenciar en voz",
	description: "Silencio de servidor. Sólo funciona si está conectada a voz.",
	requires: ["member"],
	permission: "MuteMembers",
	params: [
		{
			key: "mute",
			type: "boolean",
			required: true,
			label: "Silenciar",
			hint: "Desactivado, le quita el silencio.",
			default: true
		}
	]
},

// ─── Estadísticas ───────────────────────────────────────────────────────────
//
// No actúan sobre Discord —no hay canal que renombrar ni rol que dar—: leen
// un número y lo guardan en una variable de flujo (`save_as`) para que las
// acciones de detrás lo usen en sus campos de texto. Por eso no llevan
// `permission`. Son las dos únicas de esta familia: las que tienen un dato
// real detrás.

count_voice_members: {
	key: "count_voice_members",
	category: "stats",
	label: "Contar personas en voz",
	description: "Cuenta cuánta gente hay en un canal de voz, o en todo el servidor.",
	requires: [],
	params: [
		{
			key: "channel",
			type: "channel",
			required: false,
			label: "Canal de voz",
			hint: "Vacío = todos los canales de voz del servidor."
		},
		saveAsParam("personas_en_voz")
	]
},

count_members: {
	key: "count_members",
	category: "stats",
	label: "Contar miembros del servidor",
	description: "El total de miembros, para un canal contador o un aviso de hito.",
	requires: [],
	params: [saveAsParam("miembros")]
},

count_role_members: {
	key: "count_role_members",
	category: "stats",
	label: "Contar personas con un rol",
	description:
		"Cuenta cuánta gente tiene alguno de los roles que elijas: en todo el servidor, sólo la conectada a voz o sólo la que está en línea.",
	requires: [],
	params: [
		{
			key: "roles",
			type: "role_list",
			required: true,
			label: "Roles",
			hint: "Cuenta a quien tenga ALGUNO de estos roles."
		},
		{
			key: "scope",
			type: "select",
			required: true,
			label: "Dónde contar",
			default: "guild",
			hint: "«En línea» necesita el permiso de presencias, y cuenta a quien el bot haya visto conectarse desde que arrancó.",
			options: [
				{ value: "guild", label: "En todo el servidor" },
				{ value: "voice", label: "Sólo los conectados a voz" },
				{ value: "online", label: "Sólo los que están en línea" }
			]
		},
		saveAsParam("personas_con_rol")
	]
},

// ─── Flujo ──────────────────────────────────────────────────────────────────

wait: {
	key: "wait",
	category: "flow",
	label: "Esperar",
	description: "Pausa antes de seguir con la acción siguiente.",
	requires: [],
	params: [
		{
			key: "seconds",
			type: "number",
			required: true,
			label: "Segundos",
			// Techo bajo a propósito: la espera ocupa la ejecución entera, y una
			// espera larga multiplicada por muchos disparos ahoga el módulo.
			hint: "Como mucho 5 minutos.",
			min: 1,
			max: 300,
			default: 5
		}
	]
},

counter_set: {
	key: "counter_set",
	category: "flow",
	label: "Cambiar un contador",
	description: "Lleva la cuenta de algo para usarla luego en una condición.",
