/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

