55						client.automationRedis,
56						bot_id,
57						guild_id,
58						userId,
59						typeof raw.status === "string" ? raw.status : null
60					);
61	
62					// El freno, lo PRIMERO de los disparadores. Ver la nota de arriba.
63					const session = await openDispatch(client, bot_id, guild_id);
64					if (!session?.has("member_status_add", "member_status_remove")) return;
