import { DiscordEvents } from "@kena/sdk";
import { baseContext, toUser, withMemberFallback } from "../../engine/context-builders.js";
import { diffCustomStatus, readCustomStatus, trackPresence } from "../../engine/member-diff.js";
import { openDispatch } from "../../engine/TriggerRouter.js";
import type ModuleClient from "../../index.js";
import ModuleEventStructure from "../../structures/ModuleEventStructure.js";
import { LogType, logger } from "../../utils/logger.js";

/**
 * El estado personalizado: el textito de al lado del nombre.
 *
 * Es lo más parecido a «la descripción» que un bot puede leer. La BIO («Sobre
 * mí») no la ve nadie: Discord no la manda por gateway ni la devuelve por REST
 * a los bots. El estado sí, y viaja aquí dentro de `activities`.
 *
 * **Este evento exige el intent PRIVILEGIADO de presencias.** Sin él Discord
 * no lo manda nunca, así que los dos disparadores se pueden publicar y no
 * saltan — no hay forma de que el módulo lo detecte y avise, y por eso el
 * catálogo lo dice en el texto del disparador.
 *
 * ── El coste, que aquí es LA decisión ────────────────────────────────────────
 *
 * `PRESENCE_UPDATE` es una manguera: salta cuando alguien abre un juego, se
 * pone ausente, cambia de canción o se conecta desde el móvil, por cada
 * miembro y por cada servidor. Los demás handlers del módulo guardan su foto de
 * Redis ANTES de mirar si hay algo publicado, a propósito, para que la memoria
 * no se quede rancia. Aquí eso sería una escritura en Redis por cada latido de
 * cada usuario de cada servidor, tenga o no automatizaciones.
 *
 * Así que el orden se invierte: primero la lectura de configuración —que está
 * cacheada— y sólo si hay algo publicado se toca Redis. Lo que se paga por ello
 * es que el primer cambio de estado después de publicar la automatización no
 * dispara, sólo siembra la foto. Es el lado seguro: perder un disparo se nota
 * poco; inventarse cincuenta, mucho.
 */
class Event extends ModuleEventStructure<DiscordEvents.PRESENCE_UPDATE, ModuleClient> {
	constructor() {
		super({ name: DiscordEvents.PRESENCE_UPDATE, once: false }, async (client, presence, metadata) => {
			try {
				const { guild_id, bot_id } = metadata;
				if (!bot_id || !guild_id) return;

				const raw = presence as unknown as Record<string, unknown>;
				const rawUser = raw.user as { id?: unknown } | undefined;
				const userId = typeof rawUser?.id === "string" ? rawUser.id : null;
				if (!userId) return;

				// Quién está conectado, para «contar personas con un rol → sólo los
				// que están en línea». Se apunta ANTES del freno de abajo a
				// propósito: quien monta ese contador no tiene por qué tener además
				// una automatización de estado publicada, y sin esto el conjunto se
				// quedaría vacío para siempre. Es un `SADD` por evento — el mismo
				// orden de coste que la foto de roles de `GUILD_MEMBER_UPDATE`.
				await trackPresence(
					client.automationRedis,
					bot_id,
					guild_id,
					userId,
					typeof raw.status === "string" ? raw.status : null
				);

				// El freno, lo PRIMERO de los disparadores. Ver la nota de arriba.
				const session = await openDispatch(client, bot_id, guild_id);
				if (!session?.has("member_status_add", "member_status_remove")) return;

				const status = readCustomStatus(raw);
				const diff = await diffCustomStatus(client.automationRedis, bot_id, guild_id, userId, status);
				// Sin foto previa no se afirma nada, y una presencia que cambia por
				// otra cosa (un juego, el móvil) no es asunto de estos disparadores.
				if (!diff.known || !diff.changed) return;

				const base = await baseContext(client, bot_id, guild_id);
				// `PRESENCE_UPDATE` trae el `user` a medias —a veces sólo el id— y
				// NUNCA el member, así que el `member` lo rellena el enriquecedor de
				// siempre: una llamada al core, y sólo cuando el disparador ya ha
				// pasado el filtro.
				const ctx = {
					...base,
					user: toUser(rawUser) ?? {
						id: userId,
						username: "",
						bot: false,
						avatarUrl: null,
						createdAt: ""
					},
					status: diff.current,
					previousStatus: diff.previous
				};

				const enrich = withMemberFallback(client, guild_id, userId);

				// Los DOS, siempre: cuál de ellos es cierto depende del texto que
				// busque cada automatización, y eso lo decide `matchesTrigger` con la
				// pareja anterior/actual. Cambiar «.gg/kena» por «.gg/otra» es a la
				// vez un «se lo quitó» para una automatización y un «se lo puso» para
				// la otra.
				await session.run("member_status_add", ctx, enrich);
				await session.run("member_status_remove", ctx, enrich);
			} catch (err) {
				logger.error(LogType.ENGINE, "PresenceUpdate:", err as Error);
			}
		});
	}
}

export default Event;

