	"rename_channel",
	"set_slowmode",
	"set_channel_permission",
	// Voz
	"move_voice",
	"voice_mute",
	// Estadísticas — la primera familia de acciones que NO actúa sobre Discord:
	// recoge un dato (cuánta gente hay en voz, cuántos miembros tiene el
	// servidor, cuántos llevan un rol) y lo guarda en una variable de flujo
	// (`save_as`) para que lo usen las acciones de detrás.
	"count_voice_members",
	"count_members",
	"count_role_members",
	// Flujo
	"wait",
	"counter_set",
	"run_automation"
] as const;

export type AutomationTriggerType = (typeof AUTOMATION_TRIGGER_KEYS)[number];
export type AutomationConditionType = (typeof AUTOMATION_CONDITION_KEYS)[number];
export type AutomationActionType = (typeof AUTOMATION_ACTION_KEYS)[number];

// ─── Modo de ejecución ──────────────────────────────────────────────────────

/**
 * Cuándo se ejecuta el flujo — la primera pregunta del editor nuevo, antes
 * incluso de elegir el disparador: «todo el rato» | «cada cierto tiempo» | «a
 * una hora fija».
 *

 * reintentable en silencio, que es el fallo caro.
 *
 * `wait`, `counter_set` y `run_automation` no salen a la red, así que no pueden
 * dar 429 y no pintan nada aquí.
 */
export const RETRYABLE_ACTIONS: ReadonlySet<AutomationActionType> = new Set([
	"add_reaction",
	"pin_message",
	// Idempotente por el lado de Discord: al segundo intento contesta 40033
	// («ya estaba publicado») y el ejecutor lo lee como éxito, así que un
	// reintento no puede publicar dos veces.
	"crosspost_message",
	"add_role",
	"remove_role",
	"set_nickname",
	"timeout_member",
	"set_slowmode",
	"set_channel_permission",
	"move_voice",
	"voice_mute",
	// Sólo leen: repetir «cuenta la gente en voz», «cuenta los miembros» o
	// «cuenta quién tiene un rol» dos veces deja exactamente el mismo estado
	// que una, así que reintentar no puede hacer daño.
	"count_voice_members",
	"count_members",
	"count_role_members"
]);

/** ¿Se puede reintentar esta acción sin duplicar efectos? */
export const isRetryableAction = (type: string): boolean =>
	RETRYABLE_ACTIONS.has(type as AutomationActionType);

