	 * Cuánta gente hay AHORA en ese canal de voz, contando a quien acaba de
	 * provocar el evento. Sale del set de Redis del gateway, no de un RPC.
	 */
	{ token: "{voice_count}", requires: "voice", label: "Personas en el canal de voz" },
	{ token: "{thread}", requires: "thread", label: "Mención del hilo" }
];

/** Variables utilizables con un disparador concreto. Alimenta el autocompletado. */
export function getAvailableVariables(trigger: AutomationTriggerType): AutomationVariable[] {
	const provided = new Set<AutomationContextKey>(AUTOMATION_TRIGGERS[trigger].provides);
	return AUTOMATION_VARIABLES.filter((v) => v.requires === null || provided.has(v.requires));
}

// ─── Variables de flujo ─────────────────────────────────────────────────────

/**
 * Además del catálogo fijo de arriba, cualquier acción con un param `save_as`
 * (la familia `stats`: `count_voice_members`, `count_members`) declara una
 * variable NUEVA en tiempo de ejecución, con el nombre que le haya puesto quien
 * monta el flujo.
 *
 * No hay un catálogo estático que las liste como a `AUTOMATION_VARIABLES`:
 * cuáles existen depende de qué acciones haya DELANTE en el flujo, no del
 * disparador. Esto es lo que la dashboard usa para pintar esas fichas; el
 * motor no lo necesita — a él le basta con `ctx.vars` en tiempo de ejecución.
 */
export function flowVariables(actions: ReadonlyArray<{ type: string; params?: Record<string, unknown> }>): string[] {
	const names: string[] = [];
	const seen = new Set<string>();
	for (const { params } of actions) {
		const saveAs = params?.save_as;
		if (typeof saveAs !== "string" || saveAs === "" || seen.has(saveAs)) continue;
		seen.add(saveAs);
		names.push(saveAs);
	}
	return names;
}

