	},

	pin_message: {
		key: "pin_message",
		category: "message",
		label: "Fijar o desfijar el mensaje",
		description: "Ancla el mensaje en su canal.",
		requires: ["message"],
		permission: "ManageMessages",
		params: [
			{
				key: "action",
				type: "select",
				required: true,
				label: "Acción",
