				options: [
					{ value: "pin", label: "Fijar" },
					{ value: "unpin", label: "Desfijar" }
				]
			}
		]
	},

	crosspost_message: {
		key: "crosspost_message",
		category: "message",
		label: "Autopublicar el mensaje",
