import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

export const AUTOMATION_ACTIONS: Record<AutomationActionType, AutomationActionDef> = {
	// ─── Mensajería ─────────────────────────────────────────────────────────────

	send_message: {
		key: "send_message",
		category: "message",
		label: "Enviar un mensaje",
		description: "Publica un mensaje en el canal que elijas.",
		requires: [],
		permission: "SendMessages",
		params: [
			{ key: "channel", type: "channel", required: true, label: "Canal" },
			{
				// Mismo juego de modos que el mensaje de bienvenida, y con los mismos
				// valores: quien ya ha configurado uno reconoce el otro, y el módulo
				// puede compartir criterio en vez de tener dos formas de decir lo mismo.
				key: "mode",
				type: "select",
				// OPCIONAL aunque la interfaz lo rellene siempre: obligarlo
				// invalidaría de golpe cualquier automatización guardada antes de que
				// el campo existiera. Ausente se lee como "plain", que es justo lo que
				// esas hacían.
				required: false,
				label: "Formato",
				default: "plain",
				options: [
					{ value: "plain", label: "Texto normal" },
					{ value: "embed", label: "Embed" },
					{ value: "image", label: "Texto + imagen" },
					{ value: "embed_image", label: "Embed + imagen" }
				]
			},
			{
				key: "content",
				type: "long_text",
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
