/**
 * Acciones que es SEGURO reintentar cuando Discord contesta con un 429.
 *
 * El criterio es la idempotencia, no la importancia: aplicar dos veces «dale el
 * rol X» deja exactamente el mismo estado que aplicarla una, así que reintentar
 * no puede hacer daño. Enviar un mensaje NO lo es — el reintento publica un
 * segundo mensaje, el usuario recibe el mismo aviso dos veces y no hay forma de
 * recogerlo.
 *
 * Por eso la lista es una ALTA EXPLÍCITA y no una exclusión: al añadir una
 * acción nueva al catálogo, lo seguro por defecto es no reintentarla. Si fuese
 * una lista de excluidas, olvidarse de dar de alta la acción nueva la haría
 * reintentable en silencio, que es el fallo caro.
 *
 * `wait`, `counter_set` y `run_automation` no salen a la red, así que no pueden
 * dar 429 y no pintan nada aquí.
 */
export const RETRYABLE_ACTIONS: ReadonlySet<AutomationActionType> = new Set([
	"add_reaction",
	"pin_message",
	// Idempotente por el lado de Discord: al segundo intento contesta 40033
	// («ya estaba publicado») y el ejecutor lo lee como éxito, así que un
	// reintento no puede publicar dos veces.
	"crosspost_message",
	"add_role",
	"remove_role",
	"set_nickname",
	"timeout_member",
	"set_slowmode",
	"set_channel_permission",
	"move_voice",
	"voice_mute",
	// Sólo leen: repetir «cuenta la gente en voz», «cuenta los miembros» o
	// «cuenta quién tiene un rol» dos veces deja exactamente el mismo estado
	// que una, así que reintentar no puede hacer daño.
	"count_voice_members",
	"count_members",
	"count_role_members"
]);

/** ¿Se puede reintentar esta acción sin duplicar efectos? */
export const isRetryableAction = (type: string): boolean =>
	RETRYABLE_ACTIONS.has(type as AutomationActionType);

import { AUTOMATION_TRIGGERS } from "./triggers.js";

/**
 * Nombre de un evento de dispatch de Discord, como CADENA.
 *
 * NO se usa aquí el enum `DiscordEvents` a propósito, aunque los valores sean
 * idénticos: ese enum importa `@discordjs/ws`, y este catálogo lo consume el
 * NAVEGADOR desde la dashboard. Una sola importación de `@kena/shared` en un
 * componente de cliente arrastra gRPC al bundle, Vite intenta empaquetar `fs` y
 * el optimizador de dependencias se cae ENTERO — con él, la hidratación de
 * todas las páginas, no sólo la de automatizaciones.
 *
 * Por eso `src/automation/` no importa nada: es la condición para poder
 * exportarlo por la subruta `@kena/shared/automation` y que el cliente lo cargue
 * sin traerse medio Node detrás.
 */
export type AutomationDispatchEvent = string;

/**
 * Tipos del CATÁLOGO de automatizaciones — la única fuente de verdad sobre qué
 * disparadores, condiciones y acciones existen.
 *
 * Lo consumen las DOS puntas y por eso vive aquí:
 *
 *  - La **dashboard** pinta el selector y genera el formulario de parámetros de
 *    cada bloque leyendo estas definiciones. No hay un solo formulario escrito a
 *    mano.
 *  - El **automation-module** valida lo que le llega y decide qué ejecutor
 *    llamar.
 *
 * Con 25 acciones × 2 superficies, cualquier otro reparto acaba en deriva. Añadir
 * una acción nueva es tocar UN fichero (`actions.ts`) y escribir su ejecutor en
 * el módulo; la dashboard la recoge sola.
 */

// ─── Contexto de ejecución ────────────────────────────────────────────────────

/**
 * Piezas que puede llevar el «sobre» de una ejecución.
 *
 * Un disparador APORTA algunas (`provides`) y cada condición/acción EXIGE las
 * suyas (`requires`). De ese cruce sale la parte más importante de la UX: al
 * elegir «Entre al servidor» el selector no ofrece «Borrar el mensaje», porque
 * en ese contexto no hay ningún mensaje que borrar.
 *
 * Sin esto la interfaz deja construir automatizaciones que no pueden funcionar y
 * el fallo sólo se ve en producción, cuando ya no hay quien lo relacione.
 */
export type AutomationContextKey =
	| "user"
	| "member"
	| "channel"
	| "message"
	| "role"
	| "emoji"
	| "voice"
	| "thread";

// ─── Parámetros ───────────────────────────────────────────────────────────────

/**
 * Tipo de un parámetro. Decide tres cosas a la vez: qué control pinta la
 * dashboard, cómo se valida el valor y cómo lo lee el módulo.
 */
export type AutomationParamType =
	| "text"
	| "long_text"
	| "number"
	| "boolean"
	| "channel"
	| "channel_list"
	| "category_list"
	| "role"
	| "role_list"
	| "user"
	| "emoji"
	| "duration"
	| "select"
	| "regex"
	| "counter"
	| "automation"
	| "color"
	/** Imagen subida al CDN del bot. La dashboard pinta el campo de subida. */
	| "image"
	/**
	 * Lienzo del editor de imagen avanzado — mismo formato que usa el greeter.
	 * La dashboard pinta el editor de canvas compartido; el valor es el objeto
	 * del lienzo, o `null` si no se ha configurado ninguno.
	 */
	| "image_canvas";

/** Una opción de un parámetro `select`. */
export interface AutomationParamOption {
	value: string;
	/** Etiqueta en castellano; ver la nota de `label` en {@link AutomationParam}. */
	label: string;
}

export interface AutomationParam {
	/** Nombre del campo dentro de `params`. En inglés, como todo identificador. */
	key: string;
	type: AutomationParamType;
	required: boolean;
	/**
	 * Etiqueta en castellano, y es el FALLBACK, no el texto definitivo: la
	 * dashboard pide primero `automation.param.<key>.label` al servicio de i18n y
	 * sólo cae aquí si esa clave no existe.
	 *
	 * Está para que el catálogo funcione el día uno sin depender de dar de alta
	 * 200 traducciones antes de poder probar nada. `t()` devuelve `""` cuando la
	 * clave falta —no lanza—, así que `t(key) || param.label` resuelve solo.
	 */
	label: string;
	/** Ayuda corta bajo el control. Mismo criterio de i18n que `label`. */
	hint?: string;
	/** Opciones de un `select`. Obligatorio para ese tipo. */
	options?: AutomationParamOption[];
	/** El `select` admite varios valores (el valor pasa a ser `string[]`). */
	multiple?: boolean;
	/**
	 * Pista de PRESENTACIÓN para un `select`: sugiere pintarlo como un par de
	 * chips en vez del desplegable de siempre. Es sólo eso, una sugerencia — la
	 * dashboard decide cómo pintar cada control, el catálogo no impone nada.
	 */
	variant?: "chips";
	/** Mínimo de un `number`, o longitud mínima de un `text`. */
	min?: number;
	/** Máximo de un `number`, o longitud máxima de un `text`. */
	max?: number;
	/**
	 * Forma exacta que debe tener un `text`, como fuente de expresión regular
	 * (sin barras). La valida `validateParams` y la dashboard la usa para avisar
	 * en caliente. Ejemplo: una hora `HH:MM`.
	 */
	pattern?: string;
	/** Valor de fábrica cuando el usuario no toca el campo. */
	default?: string | number | boolean | string[] | null;
	/**
	 * El campo admite variables (`{user}`, `{channel}`…). Sólo tiene sentido en
	 * `text` / `long_text`; la dashboard le engancha el autocompletado.
	 */
	supportsVariables?: boolean;
}

// ─── Categorías ───────────────────────────────────────────────────────────────

/** Grupos del selector. Ordenan la lista larga y nada más. */
export type AutomationCategory =
	| "member"
	| "message"
	| "voice"
	| "server"
	| "stats"
	| "schedule"
	| "flow";

/**
 * Categorías de DISPARADOR agrupadas por la pregunta que responden, para que el
 * selector pueda ofrecerlas como pestañas grandes en vez de una lista de 25.
 *
 * `stats` es la que rompe el molde de MEE6: no es «cuando alguien haga algo»
 * sino «vigila este número». Por eso el chip del editor cambia de «ACTIVADOR»
 * a «RECOGER UNA ESTADÍSTICA» según lo elegido — la diferencia se ve de un
 * vistazo en vez de esconderse en el nombre del disparador.
 */
export const AUTOMATION_TRIGGER_GROUPS = [
	{ key: "action", label: "Activador", categories: ["member", "message", "voice"] },
	{ key: "stats", label: "Recoger una estadística", categories: ["stats"] },
	{ key: "schedule", label: "A una hora fija", categories: ["schedule"] },
	{ key: "server", label: "En el servidor", categories: ["server"] }
] as const satisfies ReadonlyArray<{
	key: string;
	label: string;
	categories: ReadonlyArray<AutomationCategory>;
}>;

export type AutomationTriggerGroupKey = (typeof AUTOMATION_TRIGGER_GROUPS)[number]["key"];

/** Grupo al que pertenece una categoría de disparador. */
export const triggerGroupOf = (category: AutomationCategory): AutomationTriggerGroupKey =>
	AUTOMATION_TRIGGER_GROUPS.find((g) => (g.categories as ReadonlyArray<string>).includes(category))?.key ?? "action";

// ─── Definiciones ─────────────────────────────────────────────────────────────

interface AutomationEntryBase {
	category: AutomationCategory;
	/** Etiqueta en castellano; ver la nota de `label` en {@link AutomationParam}. */
	label: string;
	/** Descripción corta para el selector. Mismo criterio de i18n. */
	description: string;
	params: AutomationParam[];
}

export interface AutomationTriggerDef extends AutomationEntryBase {
	key: AutomationTriggerType;
	/**
	 * Evento(s) de Discord que lo alimentan. TODOS tienen que estar declarados en
	 * el `events: [...]` del constructor del módulo: sin eso el core no los
	 * enruta y el handler queda MUERTO, sin ningún error que lo delate.
	 */
	events: AutomationDispatchEvent[];
	/** Piezas de contexto que este disparador pone sobre la mesa. */
	provides: AutomationContextKey[];
}

export interface AutomationConditionDef extends AutomationEntryBase {
	key: AutomationConditionType;
	/** Contexto sin el cual no se puede evaluar. */
	requires: AutomationContextKey[];
	/**
	 * ¿Tiene sentido el interruptor «no»? En casi todas sí («NO tiene el rol»),
	 * pero negar `chance` («el 30% de las veces») no significa nada útil.
	 */
	negatable: boolean;
}

export interface AutomationActionDef extends AutomationEntryBase {
	key: AutomationActionType;
	/** Contexto sin el cual no se puede ejecutar. */
	requires: AutomationContextKey[];
	/**
	 * Permiso de Discord que necesita el BOT (nombre del flag, ej.
	 * `ManageRoles`). La dashboard lo usa para avisar antes de guardar; el módulo
	 * no lo comprueba porque Discord ya contesta con un error claro.
	 */
	permission?: string;
}

// ─── Claves ───────────────────────────────────────────────────────────────────

export const AUTOMATION_TRIGGER_KEYS = [
	// Estadísticas — vigilan un NÚMERO, no una acción concreta.
	"member_count_changed",
	"voice_count_changed",

	// Horario — ninguno nace de un evento de Discord: los despierta el poller
	// del propio módulo.
	"on_schedule",
	"on_interval",

	// Miembros
	"member_join",
