export const AUTOMATION_CONDITION_KEYS = [
	"in_channel",
	"has_role",
	"has_permission",
	"message_contains",
	"message_matches",
	"message_has",
	"message_length",
	"emoji_is",
	"account_age",
	"member_age",
	"is_bot",
	"has_nickname",
	"role_count",
	"counter_compare",
	"time_window",
	"weekday",
	"rate_limit",
	"chance",
	"member_count",
	"voice_count"
] as const;

export const AUTOMATION_ACTION_KEYS = [
	// Mensajería
	"send_message",
	"send_dm",
	"reply_message",
	"send_webhook",
	"add_reaction",
	"delete_message",
	"pin_message",
	// Publica en los servidores que siguen un canal de ANUNCIOS. Sólo Discord
	// sabe si el canal lo es; en uno de texto la llamada falla con 50019.
	"crosspost_message",
	// Mensaje que se mantiene siempre el último del canal. Es la única acción
	// con estado propio: guarda en Redis el id del mensaje que puso la última
	// vez para poder borrarlo al reponerlo.
	"sticky_message",
	// Roles y miembros
	"add_role",
	"remove_role",
	"set_nickname",
	"kick_member",
	"ban_member",
	"timeout_member",
	// Canales
	"create_channel",
	"create_thread",
	"rename_channel",
	"set_slowmode",
	"set_channel_permission",
	// Voz
	"move_voice",
	"voice_mute",
	// Estadísticas — la primera familia de acciones que NO actúa sobre Discord:
	// recoge un dato (cuánta gente hay en voz, cuántos miembros tiene el
	// servidor, cuántos llevan un rol) y lo guarda en una variable de flujo
	// (`save_as`) para que lo usen las acciones de detrás.
	"count_voice_members",
	"count_members",
	"count_role_members",
	// Flujo
	"wait",
	"counter_set",
	"run_automation"
] as const;

export type AutomationTriggerType = (typeof AUTOMATION_TRIGGER_KEYS)[number];
export type AutomationConditionType = (typeof AUTOMATION_CONDITION_KEYS)[number];
export type AutomationActionType = (typeof AUTOMATION_ACTION_KEYS)[number];

// ─── Modo de ejecución ──────────────────────────────────────────────────────

/**
 * Cuándo se ejecuta el flujo — la primera pregunta del editor nuevo, antes
 * incluso de elegir el disparador: «todo el rato» | «cada cierto tiempo» | «a
 * una hora fija».
 *
 * NO es un campo de `DBAutomation`: se DERIVA del disparador elegido. Guardarlo
 * aparte pediría una migración y, peor, dejaría existir un estado imposible que
 * alguien tendría que arbitrar en ejecución — por ejemplo un `on_interval`
 * guardado con modo `always`, que contradice a su propio disparador.
 */
export const AUTOMATION_EXECUTION_MODES = ["always", "interval", "schedule"] as const;
export type AutomationExecutionMode = (typeof AUTOMATION_EXECUTION_MODES)[number];

/**
 * Modo al que pertenece un disparador. Se mira por su CLAVE y no por su
 * `category`: `on_schedule` y `on_interval` comparten la categoría `schedule`
 * (a los dos los despierta el poller, no un evento de Discord) y es justo el
 * modo el que los separa.
 */
export function executionModeOf(trigger: AutomationTriggerType): AutomationExecutionMode {
	switch (trigger) {
		case "on_interval":
			return "interval";
		case "on_schedule":
			return "schedule";
		default:
			return "always";
	}
}

/**
 * Disparadores de un modo, en el orden de `AUTOMATION_TRIGGER_KEYS`. `interval`
 * y `schedule` traen uno solo: elegir el modo ya elige el disparador, sin
 * segundo paso.
 */
export function triggersForMode(mode: AutomationExecutionMode): AutomationTriggerDef[] {
	return AUTOMATION_TRIGGER_KEYS.filter((key) => executionModeOf(key) === mode).map((key) => AUTOMATION_TRIGGERS[key]);
}

