describe("acciones de estadística", () => {
	it("count_voice_members, count_members, count_role_members y count_online_members guardan su dato con el patrón compartido de save_as", () => {
		for (const key of ["count_voice_members", "count_members", "count_role_members", "count_online_members"] as const) {
			const saveAs = AUTOMATION_ACTIONS[key].params.find((p) => p.key === "save_as");
			expect(saveAs, key).toBeDefined();
			expect(saveAs?.pattern, key).toBe("^[a-z0-9_]{1,32}$");
			expect(saveAs?.required, key).toBe(true);
		}
	});

	it("count_role_members declara roles, scope y save_as en ese orden, y se puede reintentar", () => {
		const def = AUTOMATION_ACTIONS.count_role_members;
		expect(def.params.map((p) => p.key)).toEqual(["roles", "scope", "save_as"]);

		const roles = def.params.find((p) => p.key === "roles");
		expect(roles?.type).toBe("role_list");
		expect(roles?.required).toBe(true);

		const scope = def.params.find((p) => p.key === "scope");
		expect(scope?.type).toBe("select");
		expect(scope?.required).toBe(true);
		expect(scope?.default).toBe("guild");
		// Exactamente las dos opciones del contrato — ni una de más ni de menos.
		// El motor las distingue por su `value`: cambiar uno aquí sin tocar
		// `ActionRunner` deja el contador midiendo otra cosa en silencio.
		// «En línea» no está: tiene tarjeta propia (`count_online_members`), no
		// es un tercer valor escondido aquí.
		expect(scope?.options).toEqual([
			{ value: "guild", label: "En todo el servidor" },
			{ value: "voice", label: "Sólo los conectados a voz" }
		]);

		// Sólo lee la caché: reintentarla tras un 429 no puede duplicar nada.
		expect(RETRYABLE_ACTIONS.has("count_role_members")).toBe(true);
	});

	it("count_online_members declara roles opcionales y save_as, y se puede reintentar", () => {
		const def = AUTOMATION_ACTIONS.count_online_members;
		expect(def.params.map((p) => p.key)).toEqual(["roles", "save_as"]);

		const roles = def.params.find((p) => p.key === "roles");
		expect(roles?.type).toBe("role_list");
		// A diferencia de count_role_members, sin roles «cuánta gente hay en
		// línea» sigue siendo una pregunta completa: no hace falta elegir uno.
		expect(roles?.required).toBe(false);

		expect(RETRYABLE_ACTIONS.has("count_online_members")).toBe(true);
	});
});

