			break;
		}

		case "channel":
		case "role":
		case "user": {
			if (typeof value !== "string" || !SNOWFLAKE.test(value)) {
				fail("invalid_format", `«${param.label}» no es un identificador de Discord válido.`);
			}
			break;
		}

		case "channel_list":
		case "category_list":
		case "role_list": {
			if (!Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
				break;
			}
			if (value.some((v) => typeof v !== "string" || !SNOWFLAKE.test(v))) {
				fail("invalid_format", `«${param.label}» contiene un identificador de Discord que no es válido.`);
			}
			break;
		}

		case "select": {
			const allowed = new Set((param.options ?? []).map((o) => o.value));
			const values = param.multiple ? value : [value];
			if (param.multiple && !Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser una lista.`);
				break;
			}
			for (const v of values as unknown[]) {
				if (typeof v !== "string" || !allowed.has(v)) {
					fail("unknown_option", `«${param.label}» tiene un valor que no está entre las opciones.`);
					break;
				}
			}
			break;
		}

		case "image_canvas": {
			if (typeof value !== "object" || Array.isArray(value)) {
				fail("invalid_type", `«${param.label}» tiene que ser un lienzo.`);
				break;
			}
			const canvas = value as Record<string, unknown>;
			if (typeof canvas.width !== "number" || typeof canvas.height !== "number") {
				fail("invalid_type", `«${param.label}» necesita un ancho y un alto numéricos.`);
			}
			if (!Array.isArray(canvas.elements)) {
				fail("invalid_type", `«${param.label}» necesita una lista de elementos.`);
			}
			break;
		}
	}

	return issues;
}

